{
  "givens": [
    {
      "name": "Instruction",
      "quote": "For the following exercises, describe what the two expressions represent in terms of each of the given situations. Be sure to include units."
    },
    {
      "name": "Expression 1",
      "quote": "((f(x+h)−f(x))/(h))"
    },
    {
      "name": "Expression 2",
      "quote": "(f)^(′)(x)=munder(lim, h→0)((f(x+h)−f(x))/(h))"
    },
    {
      "name": "Population Function",
      "quote": "P(x) denotes the population of a city at time x in years."
    }
  ],
  "requirements": [
    {
      "name": "Understanding of function notation",
      "necessity": "Needed to interpret f(x), P(x), and the difference quotient as values of a function at specific inputs.",
      "search_query": "function notation f(x) meaning"
    },
    {
      "name": "Definition of the difference quotient",
      "necessity": "Needed to recognize ((f(x+h)−f(x))/(h)) as the average rate of change of f over the interval [x, x+h].",
      "search_query": "difference quotient definition"
    },
    {
      "name": "Definition of the derivative",
      "necessity": "Needed to interpret (f)^(′)(x) as the limit of the difference quotient as h→0, i.e., the instantaneous rate of change of f at x.",
      "search_query": "derivative definition limit of difference quotient"
    },
    {
      "name": "Concept of limit",
      "necessity": "Needed to understand the notation lim_{h→0} and how it yields the derivative.",
      "search_query": "limit definition calculus"
    },
    {
      "name": "Units of rate of change",
      "necessity": "Needed to express the units of the difference quotient and derivative (e.g., units of f per unit of x).",
      "search_query": "units of derivative"
    },
    {
      "name": "Interpretation of population growth rate",
      "necessity": "Needed to apply the derivative concept to P(x) to describe the instantaneous rate of population change per year.",
      "search_query": "population growth rate derivative"
    },
    {
      "name": "Interpretation of average rate of change",
      "necessity": "Needed to describe the difference quotient as the average population change over a small time interval.",
      "search_query": "average rate of change population"
    }
  ]
}
